import {defaults,STATUSES,EFFORTS,allTasks,suggest,blocked,completeTask,localParts,planSchedule,addDays} from './domain.mjs';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), uid=()=>crypto.randomUUID();
const icons={now:'<path d="m12 3 1.9 6.1L20 11l-6.1 1.9L12 19l-1.9-6.1L4 11l6.1-1.9L12 3Z"/><path d="m20 3 .5 1.5L22 5l-1.5.5L20 7l-.5-1.5L18 5l1.5-.5L20 3Z"/>',projects:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',routines:'<path d="M20 7H7a4 4 0 0 0-4 4m17-4-4-4m4 4-4 4M4 17h13a4 4 0 0 0 4-4M4 17l4 4m-4-4 4-4"/>',galaxy:'<ellipse cx="12" cy="12" rx="10" ry="5" transform="rotate(-35 12 12)"/><circle cx="12" cy="12" r="2"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18m-13 5h3"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="8" cy="7" r="3" fill="currentColor"/><circle cx="16" cy="17" r="3" fill="currentColor"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-7l1-7Z"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',play:'<path d="m8 4 12 8-12 8V4Z"/>',pause:'<path d="M8 5v14M16 5v14"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m0-16a3 3 0 0 1 0 6m3 3a5 5 0 0 1 3 4v3"/>',link:'<path d="m10 13 4-4m-6 1-3 3a4 4 0 0 0 6 6l3-3m-4-8 3-3a4 4 0 0 1 6 6l-3 3"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',refresh:'<path d="M20 7v5h-5m-11 5v-5h5m10-5a8 8 0 0 0-14-2M5 17a8 8 0 0 0 14 2"/>',edit:'<path d="m15 4 5 5-11 11H4v-5L15 4Zm-2 2 5 5"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',leaf:'<path d="M20 4C9 2 2 8 5 16s17 3 15-12ZM5 20 15 9"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>'};
const icon=(n,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.projects}</svg>`;
const button=(label,action,cls='',extra='')=>`<button ${/\btype=/.test(extra)?'':'type="button"'} class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const field=(label,name,value='',type='text',extra='')=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const select=(label,name,options,value,extra='')=>`<label class="field"><span>${label}</span><select name="${name}" ${extra}>${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`}).join('')}</select></label>`;
const dateToday=()=>localParts(new Date(),state.settings.timezone).date;
const color=p=>/^#[0-9a-f]{6}$/i.test(p||'')?p:'#adacff';
const readLocal=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}};
let state={screen:'entry',entryInteracted:false,view:'now',settings:{...defaults,timezone:Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC',...readLocal('orbit-preferences',{})},projects:[],user:null,demo:true,projectId:null,settingTab:'Profile',skip:[],filter:'',epicFilter:'',galaxyProject:null,hideDone:false,calendar:null,config:{},saving:0,focus:readLocal('orbit-focus',null)};
let toastTimeout,scheduleTimeout,timerInterval;let saveQueue=Promise.resolve();let demoDocDrafts=new Map();
function seed(){const today=dateToday();const a=uid(),b=uid(),c=uid(),e1=uid(),e2=uid(),e3=uid(),e4=uid();const task=(title,firstStep,minutes,effort,status,epic,extra={})=>({id:uid(),title,firstStep,minutes,effort,status,epic,bestTime:'Any time',priority:'Medium',requirements:[],dependencies:[],repeat:'Never',dueDate:today,assignee:'',schedule:true,...extra});return [{id:a,owner_id:'demo',revision:0,data:{name:'Portfolio refresh',description:'Make room for the work you are proud of.',color:'#adacff',epics:[{id:e1,name:'Case studies'},{id:e2,name:'Website'}],tasks:[task('Choose 3 projects for your portfolio','Open your projects folder. Pick just one that makes you smile.',25,'Low','Ready',e1,{requirements:['Computer']}),task('Write the first case study','Create a blank document and give it a working title.',45,'High','Backlog',e1),task('Sketch the homepage layout','Draw three boxes on a piece of paper.',20,'Low','Doing',e2),task('Collect reference websites','Bookmark one website whose layout feels clear.',15,'Low','Done',e2)]}},{id:b,owner_id:'demo',revision:0,data:{name:'Home base',description:'Small routines that make everyday life lighter.',color:'#eabd90',epics:[{id:e3,name:'Weekly rhythm'}],tasks:[task('Reset your workspace','Put one item back where it belongs.',10,'Low','Ready',e3,{repeat:'Weekdays',bestTime:'Afternoon'}),task('Plan a few meals','Write down one meal you would like this week.',20,'Medium','Ready',e3,{repeat:'Weekly'}),task('Sort the paperwork pile','Find an empty folder and label it “To sort”.',30,'Medium','Blocked',e3)]}},{id:c,owner_id:'demo',revision:0,data:{name:'Learning lab',description:'Follow your curiosity, one small session at a time.',color:'#81ccd4',epics:[{id:e4,name:'New skills'}],tasks:[task('Practice for 15 minutes','Open your latest lesson and read the first example.',15,'Medium','Ready',e4,{repeat:'Daily',requirements:['Computer'],bestTime:'Evening'}),task('Pick a course','List one thing you would enjoy learning.',10,'Low','Done',e4)]}}];}
async function api(action,data,method=data?'POST':'GET'){const res=await fetch('/api/'+action,{method,credentials:'same-origin',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const out=await res.json().catch(()=>({error:'The server could not complete that request.'}));if(!res.ok)throw new Error(out.error||'Something went wrong. Please try again.');return out;}
function toast(message){clearTimeout(toastTimeout);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),5500);}
function persist(){if(state.demo)return;localStorage.setItem('orbit-preferences',JSON.stringify(state.settings));}
function project(id=state.projectId){return state.projects.find(p=>p.id===id);}
function findTask(id){for(const p of state.projects){const t=p.data.tasks.find(t=>t.id===id);if(t)return {p,t};}return {};}
async function mutate(p,change){const previous=structuredClone(p);change(p.data);state.saving++;persist();render();if(state.demo){state.saving--;return;}saveQueue=saveQueue.catch(()=>{}).then(async()=>{try{const result=await api('project/save',{id:p.id,data:p.data,revision:p.revision});p.revision=result.revision;autoSchedule();}catch(e){const index=state.projects.findIndex(x=>x.id===p.id);if(index>=0)state.projects[index]=previous;toast(e.message);await loadCloud(false);throw e;}finally{state.saving--;render();}});return saveQueue;}
async function saveSettings(){persist();if(!state.demo){await api('preferences',{data:state.settings});autoSchedule();}toast('Preferences saved');}
async function loadCloud(renderAfter=true){const data=await api('workspace');state.screen='app';state.user=data.user;state.demo=false;state.projects=data.projects;state.settings={...defaults,...state.settings,...data.settings,userId:data.user.id};state.calendar=data.calendar;state.projectId=state.projects.some(p=>p.id===state.projectId)?state.projectId:state.projects[0]?.id;if(renderAfter)render();}
function header(title,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${state.view==='now'?'A little momentum goes a long way':'Your workspace'}</div><h1>${title}</h1><p>${description}</p></div>${actions||`<div class="today-date">${new Intl.DateTimeFormat('en',{weekday:'long',month:'short',day:'numeric',timeZone:state.settings.timezone}).format(new Date())}</div>`}</div>`;}
function renderEntry(){return `<main class="entry-page"><div class="entry-shell"><div class="entry-brand"><img src="/icon.svg" alt=""><span>Orbit</span></div><div class="entry-content"><section class="entry-copy"><span class="entry-kicker">A calmer way to move things forward</span><h1>Make room for your next small step.</h1><p>Bring projects, tasks, and documents into one thoughtful workspace. Pick up where you left off and keep moving at your own pace.</p><div class="entry-actions">${button('Log in '+icon('arrow'),'entry-login','primary entry-primary')}${button('View demo environment','entry-demo','entry-secondary')}</div><p class="entry-signup">New to Orbit? ${button('Create an account','entry-signup','entry-link')}</p></section><aside class="entry-preview" aria-hidden="true"><div class="entry-preview-top"><span class="entry-preview-mark">${icon('now',16)}</span><span>YOUR ORBIT</span><span class="entry-preview-menu">•••</span></div><p class="entry-preview-label">YOUR NEXT SMALL MOVE</p><h2>Make the idea feel manageable.</h2><div class="entry-preview-task"><span class="entry-preview-number">1</span><span><strong>Choose a place to begin</strong><small>15 min <span>·</span> Low effort</small></span></div><div class="entry-preview-bottom"><span class="entry-preview-swatch"></span><span>One step at a time</span><span class="entry-preview-check">${icon('check',14)}</span></div></aside></div><p class="entry-note">Try sample projects in the demo. Changes reset when the page reloads.</p></div></main>`;}
function clearDemoStorage(clearFocus=false){try{for(let i=localStorage.length-1;i>=0;i--){const key=localStorage.key(i);if(key==='orbit-demo'||(key&&key.includes(':demo:')))localStorage.removeItem(key);}if(clearFocus)localStorage.removeItem('orbit-focus');}catch{}demoDocDrafts.clear();}
function enterDemo(){clearDemoStorage(true);state.screen='app';state.entryInteracted=true;state.user=null;state.demo=true;state.settings={...defaults,timezone:Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC'};state.projects=seed();state.projectId=state.projects[0]?.id;state.calendar=null;state.focus=null;state.skip=[];state.view='now';render();autoSchedule();}
function render(){if(state.screen==='entry'){document.body.classList.add('entry-mode');document.body.classList.toggle('light',state.settings.theme==='light');$('#app').innerHTML=renderEntry();return;}document.body.classList.remove('entry-mode');document.body.classList.toggle('light',state.settings.theme==='light');document.body.classList.toggle('compact',state.settings.density==='compact');document.body.classList.toggle('reduce-motion',state.settings.reducedMotion);const tasks=allTasks(state.projects),nav=[['now','Now','now'],['projects','Projects','projects'],['routines','Routines','routines'],['calendar','Calendar','calendar'],['galaxy','My universe','galaxy']];const active=['board','docs'].includes(state.view)?'projects':state.view;const view={now:renderNow,projects:renderProjects,board:renderBoard,docs:renderDocs,routines:renderRoutines,calendar:renderCalendar,galaxy:renderGalaxy,settings:renderSettings}[state.view]||renderNow;$('#app').innerHTML=`<div class="app-shell"><aside class="sidebar" aria-label="Main navigation"><div class="brand"><img src="/icon.svg" alt="">orbit</div><nav class="nav">${nav.map(([v,l,i])=>button(`${icon(i)}${l}${v==='projects'?`<span class="count">${state.projects.length}</span>`:''}`,'nav',active===v?'active':'',`data-view="${v}" ${active===v?'aria-current="page"':''}`)).join('')}</nav><div><div class="sidebar-label">In your orbit</div><div class="project-links">${state.projects.slice(0,7).map(p=>button(`<span class="swatch" style="--color:${color(p.data.color)}"></span>${esc(p.data.name)}`,'open-project','',`data-id="${p.id}"`)).join('')}${button(icon('plus')+'New project','new-project')}</div></div><div class="sidebar-bottom"><div class="sidebar-tip"><strong>One thing at a time.</strong>You can come back to the rest.</div><nav class="nav">${button(icon('settings')+'Settings','nav',state.view==='settings'?'active':'','data-view="settings"')}</nav>${button(`<span class="avatar">${state.user?esc((state.settings.name||state.user.email||'O').slice(0,2).toUpperCase()):'EX'}</span><span class="account-copy"><span>${esc(state.user?(state.settings.name||'Your workspace'):'Demo workspace')}</span><small>${esc(state.user?.email||'Log in to save and share')}</small></span>`,'account','account')}</div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">${button(icon('menu'),'menu','icon-button mobile-menu','aria-label="Open navigation"')}<span class="workspace-name">${state.demo?'Demo workspace':'Your workspace'}</span>${icon('chevron',14)}<span>${['board','docs'].includes(state.view)?esc(project()?.data.name||'Project'):nav.find(n=>n[0]===state.view)?.[1]||'Settings'}</span></div><div class="top-actions"><span class="sync-note">${state.demo?'Demo workspace':state.saving?'Saving…':'Shared workspace'}</span>${button(icon('plus')+'Add task','new-task','primary small')}</div></header><main id="main" class="main" tabindex="-1">${state.demo?`<div class="demo-banner">${icon('projects',17)}<span>You're exploring the demo. Changes reset when the page reloads.</span>${button('Log in','account','quiet small')}</div>`:''}${view(tasks)}</main></div></div>`;}
function renderNow(tasks){const candidates=suggest(state.projects,state.settings,new Date(),state.skip),t=candidates[0],name=state.settings.name?`, ${esc(state.settings.name.split(' ')[0])}`:'';const local=localParts(new Date(),state.settings.timezone),greeting=local.hour<12?'Good morning':local.hour<17?'Good afternoon':'Good evening';const done=tasks.filter(t=>t.status==='Done').length,routines=tasks.filter(t=>t.repeat!=='Never'&&t.repeat&&(!t.dueDate||t.dueDate<=dateToday())).slice(0,3);return header(`${greeting}${name}.`,'You don’t have to do it all. Just find your next step.')+`<div class="now-layout"><section><div class="context-bar"><label>${icon('bolt',16)} My energy <select aria-label="Current energy" data-pref="energy">${EFFORTS.map(e=>`<option ${state.settings.energy===e?'selected':''}>${e}</option>`).join('')}</select></label><label>${icon('clock',16)} I have <select aria-label="Available time" data-pref="minutes">${[5,10,15,25,30,45,60,90].map(n=>`<option value="${n}" ${Number(state.settings.minutes)===n?'selected':''}>${n} min</option>`).join('')}</select></label>${button('Available tools','contexts','quiet small context-edit')}</div>${t?`<article class="panel next-card"><div class="eyebrow">${icon('now',17)} Your next small move</div><div class="next-project"><span class="swatch" style="--color:${color(t.projectColor)}"></span>${esc(t.projectName)} <span> / </span> ${esc(t.epicName)}</div><h2>${esc(t.title)}</h2><div class="tags"><span class="tag">${icon('clock')}${t.minutes} min</span><span class="tag">${icon('bolt')}${esc(t.effort)} effort</span>${t.requirements.map(r=>`<span class="tag">${esc(r)}</span>`).join('')}</div><div class="step-box"><span class="step-number">1</span><div><p class="step-label">Start here · one tiny step</p><p>${esc(t.firstStep||'Open what you need and spend two minutes getting started.')}</p></div></div><div class="next-actions">${button(icon('play')+(state.focus?.taskId===t.id?'Resume this task':'Let’s start'),'start-task','primary',`data-id="${t.id}"`)}${button('Something else','skip','quiet',`data-id="${t.id}"`)}${button(icon('check'),'complete','icon-button quiet',`data-id="${t.id}" aria-label="Mark task complete"`)}</div><div class="reason"><strong>Why this?</strong> ${t.reason.map(esc).join(' · ')}. Required tools and dependencies are ready.</div></article>`:`<article class="panel empty">${icon('leaf')}<h2>${tasks.length?'Nothing needs forcing.':'Give your ideas a home.'}</h2><p>${tasks.length?'No ready task fits your current time, energy, and available tools. Adjust them above, or move a task to Ready.':'Create a project, then add one task with a small first step.'}</p>${button(tasks.length?'Show all projects':'Create a project',tasks.length?'show-projects':'new-project','primary')}${state.skip.length?button('Show skipped suggestions','reset-skip','quiet'):''}</article>`}<h2 class="section-title">A little progress, across your projects <small>${state.projects.length} projects</small></h2><div class="project-list">${state.projects.slice(0,4).map(p=>{const completed=p.data.tasks.filter(t=>t.status==='Done').length,total=p.data.tasks.length;return button(`<span class="project-icon" style="--color:${color(p.data.color)}">${icon('projects',19)}</span><span class="copy"><strong>${esc(p.data.name)}</strong><small>${total-completed} unfinished · ${p.data.epics.length} epics</small></span><span class="progress" aria-label="${completed} of ${total} tasks complete" style="--color:${color(p.data.color)}"><span style="width:${total?completed/total*100:0}%"></span></span>${icon('chevron',16)}`,'open-project','project-row',`data-id="${p.id}"`)}).join('')}</div></section><aside class="right-stack"><section class="panel"><h3>Your orbit, at a glance</h3><div class="pulse-number">${tasks.filter(t=>t.status!=='Done').length}<span style="font-size:1rem;color:var(--muted);letter-spacing:0"> open tasks</span></div><p class="pulse-label">Across ${state.projects.length} little worlds</p><div class="progress"><span style="width:${tasks.length?done/tasks.length*100:0}%"></span></div><div class="mini-stats"><div><strong>${done}</strong><span>completed</span></div><div><strong>${tasks.filter(t=>t.status==='Doing').length}</strong><span>in motion</span></div></div>${button('Explore your universe '+icon('arrow'),'nav','text-link','data-view="galaxy"')}</section><section class="panel"><h3>Your recurring rhythm</h3>${routines.length?routines.map(t=>`<div class="routine-mini">${button('','complete','check-button',`data-id="${t.id}" aria-label="Complete ${esc(t.title)}"`)}<div><p>${esc(t.title)}</p><small>${t.minutes} min · ${esc(t.repeat)}</small></div></div>`).join(''):'<p class="muted" style="font-size:.875rem">No routines due today.</p>'}${button('See all routines '+icon('arrow'),'nav','text-link','data-view="routines"')}</section><section class="panel"><h3>${icon('calendar',16)} Make space for it</h3><p class="muted" style="font-size:.875rem">${state.calendar?.connected?'Your tasks are scheduled around your connected calendars.':'Connect Google Calendar to fit tasks around what’s already in your day.'}</p>${button(state.calendar?.connected?'View your schedule':'Connect calendar','calendar-settings','small')}</section></aside></div>`;}
function renderProjects(){return header('Every project has a place.','Open a board, find a thread, and pick it back up.',`<div class="heading-actions">${button(icon('plus')+'New project','new-project','primary')}</div>`)+(state.projects.length?`<div class="projects-grid">${state.projects.map(p=>{const total=p.data.tasks.length,done=p.data.tasks.filter(t=>t.status==='Done').length;return button(`<span class="project-icon" style="--color:${color(p.data.color)}">${icon('projects',22)}</span><span class="arrow">${icon('arrow')}</span><h2>${esc(p.data.name)}</h2><p>${esc(p.data.description||'One small step at a time.')}</p><span class="progress" style="--color:${color(p.data.color)}"><span style="width:${total?done/total*100:0}%"></span></span><span class="meta"><span>${total-done} unfinished tasks</span><span>${done}/${total} done</span></span>`,'open-project','project-card',`data-id="${p.id}"`)}).join('')}</div>`:`<section class="panel empty">${icon('projects')}<h2>Your first project starts here.</h2><p>Give it a name. You can figure out the rest as you go.</p>${button('Create a project','new-project','primary')}</section>`);}
function renderBoard(){const p=project();if(!p)return renderProjects();const filtered=p.data.tasks.filter(t=>(!state.filter||t.title.toLowerCase().includes(state.filter.toLowerCase()))&&(!state.epicFilter||t.epic===state.epicFilter));return header(esc(p.data.name),esc(p.data.description||'Move your work forward, one ticket at a time.'),`<div class="heading-actions">${button('Docs','docs','small')}${button(icon('users')+'Members','members','small')}${button(icon('edit')+'Project','edit-project','small')}${button(icon('plus')+'Task','new-task','primary small')}</div>`)+`<div class="board-tools"><div class="filters"><input id="task-search" aria-label="Search tasks" placeholder="Find a task…" value="${esc(state.filter)}"><select id="epic-filter" aria-label="Filter by epic"><option value="">All epics</option>${p.data.epics.map(e=>`<option value="${e.id}" ${state.epicFilter===e.id?'selected':''}>${esc(e.name)}</option>`).join('')}</select></div>${button(icon('plus')+'Add epic','new-epic','quiet small')}</div><div class="board">${STATUSES.map((status,i)=>`<section class="column" data-status="${status}" aria-label="${status}"><div class="column-head"><span class="status-dot" style="background:${['#8790a6','#adacff','#eabd90','#f09284','#a6d792'][i]}"></span>${status}<span class="count">${filtered.filter(t=>t.status===status).length}</span>${button(icon('plus',15),'new-task','',`data-status="${status}" aria-label="Add task to ${status}"`)}</div>${filtered.filter(t=>t.status===status).map(t=>ticket(t,p)).join('')}${button(icon('plus',14)+'Add task','new-task','column-add',`data-status="${status}"`)}</section>`).join('')}</div>`;}
function ticket(t,p){const e=p.data.epics.find(e=>e.id===t.epic);return `<article class="ticket" draggable="true" tabindex="0" role="button" data-action="task-detail" data-id="${t.id}" aria-label="Edit ${esc(t.title)}. Current status: ${t.status}"><p class="epic" style="--color:${color(p.data.color)}">${icon('link',12)}${esc(e?.name||'Independent task')}</p><h3>${esc(t.title)}</h3><div class="tiny-step">${esc(t.firstStep||'Add a tiny first step…')}</div><div class="tags"><span class="tag">${esc(t.effort)} effort</span>${t.repeat&&t.repeat!=='Never'?`<span class="tag">${icon('routines')}${esc(t.repeat)}</span>`:''}${t.dependencies?.length?`<span class="tag">${t.dependencies.length} dependencies</span>`:''}</div><div class="ticket-foot"><span class="time">${t.minutes} min${t.dueDate?' · '+esc(t.dueDate.slice(5)):''}</span><span class="avatar" title="${t.assignee?'Assigned':'Unassigned'}">${t.assignee?'M':'—'}</span></div></article>`;}
function renderRoutines(tasks){const rows=tasks.filter(t=>t.repeat&&t.repeat!=='Never');return header('A rhythm you can return to.','Recurring tasks carry their own effort, timing, and requirements.',`<div class="heading-actions">${button(icon('plus')+'New routine','new-routine','primary')}</div>`)+(rows.length?`<div class="table-wrap"><table class="routine-table"><thead><tr><th>Routine</th><th>Repeats</th><th>Effort</th><th>Best time</th><th>Next due</th><th></th></tr></thead><tbody>${rows.map(t=>`<tr><td><strong>${esc(t.title)}</strong><small><span class="swatch" style="--color:${color(t.projectColor)}"></span> ${esc(t.projectName)} · ${t.minutes} min</small></td><td>${esc(t.repeat)}</td><td><span class="tag">${esc(t.effort)}</span></td><td>${esc(t.bestTime)}</td><td>${esc(t.dueDate||'Unscheduled')}</td><td>${button(icon('edit'),'task-detail','icon-button quiet',`data-id="${t.id}" aria-label="Edit ${esc(t.title)}"`)}${button(icon('check'),'complete','icon-button quiet',`data-id="${t.id}" aria-label="Complete ${esc(t.title)}"`)}</td></tr>`).join('')}</tbody></table></div><p class="muted" style="font-size:.8125rem">When you finish a routine, its next occurrence becomes ready. Missed occurrences don’t pile up.</p>`:`<div class="panel empty">${icon('routines')}<h2>Make a little room for repetition.</h2><p>Add a daily, weekday, weekly, or monthly routine.</p>${button('Add a routine','new-routine','primary')}</div>`);}
function renderGalaxy(tasks){const selected=project(state.galaxyProject),ps=selected?[selected]:state.projects;if(!ps.length)return header('Your universe.','Projects are galaxies. Epics connect their stars.')+renderProjects();const W=1000,H=selected?560:Math.max(550,Math.ceil(ps.length/3)*310),positions=ps.map((p,i)=>({p,x:selected?500:170+(i%3)*330,y:selected?285:175+Math.floor(i/3)*300}));let content=`<defs>${ps.map(p=>`<radialGradient id="glow-${p.id}"><stop stop-color="${color(p.data.color)}" stop-opacity=".13"/><stop offset="1" stop-color="${color(p.data.color)}" stop-opacity="0"/></radialGradient>`).join('')}</defs>`;for(const {p,x,y} of positions){const ts=p.data.tasks.filter(t=>!state.hideDone||t.status!=='Done'),r=selected?190:90,groups=[...new Set(ts.map(t=>t.epic||'none'))];content+=`<circle cx="${x}" cy="${y}" r="${r+55}" fill="url(#glow-${p.id})"/><circle cx="${x}" cy="${y}" r="${r+18}" fill="none" stroke="${color(p.data.color)}" stroke-opacity=".13" stroke-dasharray="3 8"/>`;const nodes=ts.map((t,i)=>{const group=groups.indexOf(t.epic||'none'),angle=group/Math.max(groups.length,1)*Math.PI*2-.7,within=ts.filter(k=>(k.epic||'none')===(t.epic||'none')).findIndex(k=>k.id===t.id),spread=selected?52:25,cx=x+Math.cos(angle)*r*.58+Math.cos(within*2.4)*spread*(.7+within*.16),cy=y+Math.sin(angle)*r*.58+Math.sin(within*2.4)*spread*(.7+within*.16);return {t,cx,cy}});for(const group of groups){const groupNodes=nodes.filter(n=>(n.t.epic||'none')===group);groupNodes.slice(1).forEach((n,i)=>{const prev=groupNodes[i];content+=`<line x1="${prev.cx}" y1="${prev.cy}" x2="${n.cx}" y2="${n.cy}" stroke="${color(p.data.color)}" stroke-width="1" stroke-opacity=".35"/>`});if(selected&&groupNodes[0]){const n=groupNodes[0];content+=`<text x="${n.cx}" y="${n.cy-35}" text-anchor="middle" font-size="14" fill-opacity=".7">${esc(p.data.epics.find(e=>e.id===group)?.name||'Independent tasks')}</text>`;}}nodes.forEach(({t,cx,cy})=>{const done=t.status==='Done',b=blocked(t,tasks);content+=`<g class="star" role="button" tabindex="0" data-action="task-detail" data-id="${t.id}" aria-label="${esc(t.title)}, ${t.status}"><title>${esc(t.title)} — ${t.status}</title><circle cx="${cx}" cy="${cy}" r="15" fill="transparent"/><circle cx="${cx}" cy="${cy}" r="${done?3:6}" fill="${b?'#101420':color(p.data.color)}" opacity="${done?.3:1}" stroke="${color(p.data.color)}" stroke-width="${b?2:0}"/>${!done&&!b?`<circle cx="${cx}" cy="${cy}" r="11" fill="${color(p.data.color)}" opacity=".09"/>`:''}</g>`});content+=`<g class="project-node" role="button" tabindex="0" data-action="galaxy-project" data-id="${p.id}" aria-label="Explore ${esc(p.data.name)}"><text x="${x}" y="${y+r+50}" text-anchor="middle" font-size="${selected?21:17}" font-weight="500">${esc(p.data.name)}</text><text x="${x}" y="${y+r+74}" text-anchor="middle" font-size="13" fill-opacity=".5">${p.data.tasks.filter(t=>t.status!=='Done').length} unfinished · ${p.data.epics.length} epics</text></g>`;}return header(selected?esc(selected.data.name):'See the bigger picture.','Projects are galaxies. Epics connect their stars. Select a star to pick up a task.',`<div class="heading-actions">${selected?button('All galaxies','galaxy-back','small'):' '}${button(state.hideDone?'Show completed':'Hide completed','galaxy-done','small')}${selected?button('Open project board','open-project','primary small',`data-id="${selected.id}"`):''}</div>`)+`<section class="galaxy-panel"><div class="galaxy-toolbar"><span>${selected?'Project / Epic / Task':'Universe / Project / Epic / Task'}</span>${button(icon('refresh')+'Reset view','galaxy-back','small')}</div><svg class="galaxy-svg" viewBox="0 0 ${W} ${H}" role="group" aria-label="Interactive project galaxy map">${content}</svg><div class="galaxy-legend"><span><span class="swatch" style="--color:#adacff"></span>Unfinished</span><span>◌ Blocked</span><span style="opacity:.55">• Completed</span><span>— Same epic</span></div></section><div class="galaxy-summary"><div class="panel"><strong>${ps.length}</strong><span>${selected?'galaxy in view':'project galaxies'}</span></div><div class="panel"><strong>${ps.reduce((n,p)=>n+p.data.epics.length,0)}</strong><span>epic constellations</span></div><div class="panel"><strong>${ps.reduce((n,p)=>n+p.data.tasks.filter(t=>t.status!=='Done').length,0)}</strong><span>unfinished stars</span></div></div>`;}
function renderCalendar(){const plan=state.calendar?.state?.plan,preview=state.demo?planSchedule(state.projects,state.settings,[],new Date(),7):null,events=plan?.scheduled||preview?.scheduled||[];let previous='';return header('Space for your next steps.','A seven-day plan around your existing events and preferred hours.',`<div class="heading-actions">${button(icon('settings')+'Preferences','calendar-settings','small')}${button(icon('refresh')+'Schedule now','sync-calendar','primary small')}</div>`)+(!state.calendar?.connected?`<div class="notice">${state.demo?'Example plan only. No Google events have been read or created.':'Google Calendar is not connected yet. Connect it to check your availability and place tasks into real free slots.'} ${button('Calendar connection','calendar-settings','small')}</div>`:`<p class="muted" style="font-size:.875rem">Last scheduled: ${esc(state.calendar.state?.lastSync?new Date(state.calendar.state.lastSync).toLocaleString():'Not yet')} · Daily refresh, plus updates while you use Orbit.</p>`)+(state.calendar?.state?.error?`<div class="notice">${esc(state.calendar.state.error)}</div>`:'')+(events.length?`<div class="calendar-list">${events.slice().sort((a,b)=>a.start.localeCompare(b.start)).map(t=>{const d=localParts(t.start,state.settings.timezone).date,heading=previous!==d?`<h2 class="calendar-day">${esc(new Intl.DateTimeFormat('en',{timeZone:state.settings.timezone,weekday:'long',month:'short',day:'numeric'}).format(new Date(t.start)))}</h2>`:'';previous=d;const format=iso=>new Intl.DateTimeFormat('en',{timeZone:state.settings.timezone,hour:'numeric',minute:'2-digit'}).format(new Date(iso));return `${heading}<div class="calendar-event" style="--color:${color(t.projectColor)}"><div class="event-time">${format(t.start)} – ${format(t.end)}</div><div><strong>${esc(t.title)}</strong><small>${esc(t.projectName)} · ${esc(t.firstStep)}</small></div><span class="tag">${preview?'Example':t.eventId?'On Google Calendar':'Scheduled'}</span></div>`}).join('')}</div>`:`<div class="panel empty">${icon('calendar')}<h2>Your calendar can hold the plan.</h2><p>Connect Google Calendar, add tasks in Ready or Doing, and choose your scheduling hours.</p>${button('Calendar settings','calendar-settings','primary')}</div>`)+((plan?.unscheduled||preview?.unscheduled||[]).length?`<section class="panel" style="margin-top:25px"><h3>Still needs a little space</h3>${(plan?.unscheduled||preview.unscheduled).map(t=>`<p class="muted" style="font-size:.875rem"><strong>${esc(t.title)}</strong> · ${esc(t.occurrence)}<br>${esc(t.reason)}</p>`).join('')}</section>`:'');}
function renderSettings(){const tabs=['Profile','Focus & energy','Tasks & routines','Calendar','Collaboration','Appearance','Data & privacy'];return header('Make Orbit work for you.','A few preferences, fewer decisions later.')+`<div class="settings-layout"><nav class="settings-nav" role="tablist" aria-label="Settings">${tabs.map(t=>button(esc(t),'settings-tab',state.settingTab===t?'active':'',`data-tab="${esc(t)}" role="tab" aria-selected="${state.settingTab===t}" aria-controls="settings-panel"`)).join('')}</nav><section id="settings-panel" class="panel settings-content" role="tabpanel"><form id="settings-form"><h2>${esc(state.settingTab)}</h2>${settingsFields()}${!['Collaboration','Data & privacy'].includes(state.settingTab)?'<div class="settings-footer"><button type="submit" class="primary">Save preferences</button></div>':''}</form></section></div>`;}
function settingsFields(){const s=state.settings;switch(state.settingTab){case 'Profile':return `<p class="intro">A familiar name and the right local time.</p>${field('Your name','name',s.name,'text','maxlength="60"')}${field('Time zone','timezone',s.timezone,'text','required list="timezones"')}<datalist id="timezones">${['Europe/Amsterdam','Europe/London','Europe/Belgrade','America/New_York','America/Los_Angeles','Asia/Kolkata','Australia/Sydney','UTC'].map(x=>`<option>${x}</option>`).join('')}</datalist><p class="muted" style="font-size:.875rem">${state.user?`Signed in as ${esc(state.user.email)}`:'You’re exploring locally. Sign in for shared projects and access across devices.'}</p>${button(state.user?'Sign out':'Sign in','account-action','small','type="button"')}`;case 'Focus & energy':return `<p class="intro">Suggestions use these defaults. You can change your energy and available time on the Now page whenever you need.</p><div class="form-grid">${select('Default energy','energy',EFFORTS,s.energy)}${select('Available time','minutes',[5,10,15,25,30,45,60,90].map(x=>[String(x),x+' minutes']),String(s.minutes))}</div>${field('Tools and places available now','contexts',s.contexts.join(', '))}<p class="muted" style="font-size:.8125rem">Separate values with commas, such as Computer, Internet, Home. Tasks appear when all their requirements are available and their dependencies are complete.</p>`;case 'Tasks & routines':return `<p class="intro">Defaults for new tasks. Every task can have its own values.</p><div class="form-grid">${select('Required effort','defaultEffort',EFFORTS,s.defaultEffort)}${field('Duration in minutes','defaultMinutes',s.defaultMinutes,'number','min="1" max="480" required')}${select('Best time of day','defaultTime',['Any time','Morning','Afternoon','Evening'],s.defaultTime)}</div><div class="notice">Completed routines move to their next due date. Missed repetitions are skipped when you complete the routine, so they never become a pile of overdue copies.</div>`;case 'Calendar':return `<p class="intro">Orbit checks the calendars you select, leaves breathing room, and creates separate events for each task occurrence. Only your assigned or unassigned tasks are scheduled.</p><div class="field"><span>Google Calendar</span><div>${state.calendar?.connected?`<span class="success-note">Connected</span> ${button('Disconnect','disconnect-calendar','small','type="button"')}`:button(icon('calendar')+'Connect Google Calendar','connect-google','primary','type="button"')}</div><small>${state.config.googleConfigured?'Each collaborator connects their own Google account.':'Calendar connection needs secure Google and scheduling settings. The rest of Orbit is available now.'}</small></div>${!state.config.googleConfigured?'<div class="notice">To activate: add GOOGLE_CLIENT_ID, GOOGLE_CLIENT_SECRET, TOKEN_ENCRYPTION_KEY, and CRON_SECRET in the project’s secure environment settings, then redeploy. Never place private keys in source files. <a href="https://vercel.com/mjeremic-9407/orbit-focus-workspace/settings/environment-variables" target="_blank" rel="noreferrer">Open Vercel settings</a>. Register <strong>'+esc(location.origin)+'/api/google/callback</strong> as the Google OAuth redirect URI.</div>':''}<label class="check-row"><input type="checkbox" name="autoSchedule" ${s.autoSchedule?'checked':''}>Automatically schedule and refresh tasks</label><div class="form-grid">${field('Start hour (0–23)','dayStart',s.dayStart,'number','min="0" max="23" required')}${field('End hour (1–24)','dayEnd',s.dayEnd,'number','min="1" max="24" required')}${field('Break between events (minutes)','buffer',s.buffer,'number','min="0" max="60" required')}${field('Phone reminder (minutes before)','reminder',s.reminder,'number','min="0" max="120" required')}</div><div class="field"><span>Scheduling days</span><div class="check-options">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((d,i)=>`<label class="check-chip"><input type="checkbox" name="workDays" value="${i}" ${s.workDays.includes(i)?'checked':''}>${d}</label>`).join('')}</div></div>${field('Calendars to check (IDs, separated by commas)','calendarIds',s.calendarIds.join(', '))}${field('Calendar for Orbit events','targetCalendar',s.targetCalendar)}<p class="muted" style="font-size:.8125rem">Use primary for your main calendar. For another calendar, copy its Calendar ID from Google Calendar → Settings → Integrate calendar. Orbit refreshes daily and when you change tasks. It plans seven days ahead; calendar changes between refreshes can temporarily create conflicts.</p>`;case 'Collaboration':return `<p class="intro">Share individual projects through a one-use invitation link. Only the owner can invite or remove members. Members can edit tasks and epics.</p>${state.projects.map(p=>`<div class="member-row"><span class="swatch" style="--color:${color(p.data.color)}"></span><span>${esc(p.data.name)}</span>${button('Members','members','small',`type="button" data-id="${p.id}"`)}</div>`).join('')||'<p class="muted">Create a project to invite your first collaborator.</p>'}`;case 'Appearance':return `<p class="intro">Keep your workspace comfortable to return to.</p>${select('Theme','theme',['dark','light'].map(x=>[x,x==='dark'?'Night sky':'Daylight']),s.theme)}${select('Board density','density',[['comfortable','Comfortable'],['compact','Compact']],s.density)}<label class="check-row"><input type="checkbox" name="reducedMotion" ${s.reducedMotion?'checked':''}>Reduce motion</label>`;case 'Data & privacy':return `<p class="intro">${state.demo?'Log in to save your projects and share them with others.':'Your signed-in projects are stored with access limited to their members. Your Google connection is private to your account.'}</p>${button(icon('download')+'Export my workspace','export','small','type="button"')}<p class="muted" style="font-size:.8125rem">Export includes projects and preferences. It excludes passwords, sessions, and Google credentials.</p>${state.demo?button('Log in to save your workspace','account','small'):button('Sign out of this device','logout','small','type="button"')}<div class="notice">${state.demo?'Changes in the demo reset when the page reloads.':'Shared changes save to the cloud. If a teammate edits the same project at the same time, Orbit asks you to reload instead of silently replacing their changes.'}</div>`;}}
function modal(title,body){const d=$('#modal');d.innerHTML=`<div class="modal-head"><h2>${title}</h2>${button(icon('close'),'close-modal','icon-button quiet','aria-label="Close dialog"')}</div><div class="modal-body">${body}</div>`;if(!d.open)d.showModal();}
function closeModal(){clearInterval(timerInterval);$('#modal').close();}
function authModal(mode='signin'){modal(mode==='signin'?'Welcome back to your orbit.':'Make room for your projects.',`<div class="auth-tabs">${button('Sign in','auth-mode',mode==='signin'?'active':'','data-mode="signin"')}${button('Create account','auth-mode',mode==='signup'?'active':'','data-mode="signup"')}</div><form id="auth-form" data-mode="${mode}">${field('Email address','email','','email','required autocomplete="email"')}${field('Password','password','','password',`required minlength="8" autocomplete="${mode==='signin'?'current-password':'new-password'}"`)}<p class="form-error" id="auth-error"></p><button class="primary" type="submit">${mode==='signin'?'Sign in':'Create account'}</button><p class="muted" style="font-size:.8125rem">Shared projects are private to their members. ${mode==='signup'?'Confirm your email before signing in.':''}</p></form>`);}
function projectModal(edit=false){const p=edit?project():null;modal(edit?'Edit project':'A new little world.',`<form id="project-form" data-id="${p?.id||''}">${field('Project name','name',p?.data.name||'','text','required maxlength="80" placeholder="What are you working on?"')}<label class="field"><span>A little context</span><textarea name="description" maxlength="350" placeholder="What would you like to make happen?">${esc(p?.data.description||'')}</textarea></label>${field('Galaxy color','color',p?.data.color||'#adacff','color')}<div class="modal-footer">${p?button('Delete project','delete-project','danger small',`type="button" data-id="${p.id}"`):''}${button('Cancel','close-modal','','type="button"')}<button type="submit" class="primary">${p?'Save changes':'Create project'}</button></div></form>`);}
async function taskModal(id=null,routine=false,status='Ready'){if(!state.projects.length){toast('Create a project first, then add its first task.');projectModal();return;}const found=id?findTask(id):{},p=found.p||project()||state.projects[0],t=found.t||{},s=state.settings;let members=[];if(!state.demo)try{members=(await api('members?project='+p.id)).members}catch{};modal(id?'A task, one step at a time.':routine?'Build a recurring rhythm.':'Get it out of your head.',`<form id="task-form" data-id="${id||''}">${field('Task','title',t.title||'','text','required maxlength="180" placeholder="What needs doing?"')}<label class="field"><span>The tiniest first step</span><textarea name="firstStep" maxlength="500" required placeholder="Something you can start in two minutes…">${esc(t.firstStep||'')}</textarea></label><div class="form-grid">${select('Project','projectId',state.projects.map(p=>[p.id,p.data.name]),p.id,id?'disabled':'id="task-project-select"')}${select('Epic','epic',[['','Independent task'],...p.data.epics.map(e=>[e.id,e.name])],t.epic||'','id="task-epic-select"')}${select('Status','status',STATUSES,t.status||status)}${select('Required effort','effort',EFFORTS,t.effort||s.defaultEffort)}${field('Estimated minutes','minutes',t.minutes||s.defaultMinutes,'number','min="1" max="480" required')}${select('Best time of day','bestTime',['Any time','Morning','Afternoon','Evening'],t.bestTime||s.defaultTime)}${select('Repeats','repeat',['Never','Daily','Weekdays','Weekly','Monthly'],t.repeat||(routine?'Daily':'Never'))}${field('Due / first occurrence','dueDate',t.dueDate||dateToday(),'date','required')}${select('Priority','priority',['Low','Medium','High'],t.priority||'Medium')}${select('Assigned to','assignee',[['','Unassigned'],...(state.user?[[state.user.id,'Me']]:[]),...members.filter(m=>m.user_id!==state.user?.id).map(m=>[m.user_id,m.display_name||'Project member'])],t.assignee||'')}<div class="full">${field('Requirements (separate with commas)','requirements',(t.requirements||[]).join(', '),'text','placeholder="Computer, Internet, Home…"')}</div><label class="field full"><span>Tasks that must finish first</span><select name="dependencies" multiple size="3">${p.data.tasks.filter(k=>k.id!==id).map(k=>`<option value="${k.id}" ${t.dependencies?.includes(k.id)?'selected':''}>${esc(k.title)}</option>`).join('')}</select><small>Use Ctrl / Cmd to select more than one. A task waits until all selected dependencies are complete.</small></label></div><label class="check-row"><input type="checkbox" name="schedule" ${t.schedule!==false?'checked':''}>Include in automatic calendar scheduling</label><p class="form-error" id="task-error"></p><div class="modal-footer">${id?button('Delete','delete-task','danger small',`type="button" data-id="${id}"`):''}${button('Cancel','close-modal','','type="button"')}<button type="submit" class="primary">Save task</button></div></form>`);}
function contextModal(){modal('What’s available right now?',`<form id="contexts-form">${field('Tools, places, and requirements you have','contexts',state.settings.contexts.join(', '))}<p class="muted" style="font-size:.875rem">Separate each with a comma. Match the requirements on your tasks, such as Computer, Internet, Home.</p><div class="modal-footer"><button class="primary" type="submit">Find my next step</button></div></form>`);}
function focusModal(id){const {p,t}=findTask(id);if(!t)return;const old=state.focus?.taskId===id?state.focus:null;state.focus=old||{taskId:id,end:Date.now()+5*60000,paused:false,remaining:300000};if(!state.demo)localStorage.setItem('orbit-focus',JSON.stringify(state.focus));if(t.status!=='Doing')mutate(p,data=>{data.tasks.find(k=>k.id===id).status='Doing'}).catch(e=>toast(e.message));modal('Just this. For a little while.',`<p class="eyebrow" style="text-align:center">${esc(p.data.name)}</p><h3 style="text-align:center;line-height:1.5;font-weight:500">${esc(t.title)}</h3><p class="focus-step">${esc(t.firstStep)}</p><div id="focus-time" class="focus-timer">5:00</div><p class="muted" style="text-align:center;font-size:.875rem">Five minutes is a starting point. You can stop or keep going.</p><div class="focus-actions">${button(icon('pause')+'Pause / resume','pause-focus','small')}${button(icon('check')+'Task finished','complete','primary',`data-id="${id}"`)}</div>`);const tick=()=>{const f=state.focus;if(!f||!$('#focus-time'))return;const ms=f.paused?f.remaining:Math.max(0,f.end-Date.now()),sec=Math.ceil(ms/1000);$('#focus-time').textContent=Math.floor(sec/60)+':'+String(sec%60).padStart(2,'0');};clearInterval(timerInterval);tick();timerInterval=setInterval(tick,500);}
async function membersModal(id=state.projectId){const p=project(id);if(!p)return;state.projectId=id;if(state.demo){modal('Bring someone into your orbit.',`<p class="muted">Sign in to create shared projects and invite collaborators. Demo workspace changes are temporary.</p>${button('Sign in','account','primary')}`);return;}const out=await api('members?project='+id);const owner=p.owner_id===state.user.id;modal('People in '+esc(p.data.name),`<p class="muted" style="font-size:.875rem">${owner?'Create a one-use invitation link. It expires in seven days. Copy it and share it with the person you want to join.':'Project members can edit tasks and epics. The owner manages invitations.'}</p>${out.members.map(m=>`<div class="member-row"><span class="avatar">${esc((m.display_name||'M').slice(0,2).toUpperCase())}</span><span>${esc(m.display_name||'Project owner')} <small>${m.user_id===p.owner_id?'Owner':'Member'}</small></span>${owner&&m.user_id!==p.owner_id?button('Remove','remove-member','danger small',`data-user="${m.user_id}" data-id="${p.id}"`):''}</div>`).join('')}<div id="invite-result"></div>${owner?`<div style="margin-top:22px">${button(icon('link')+'Create invitation link','create-invite','primary small',`data-id="${p.id}"`)}</div>`:''}`);}
async function syncCalendar(){if(state.demo){toast('Sign in and connect Google Calendar to create real events.');state.view='settings';state.settingTab='Calendar';render();return;}if(!state.calendar?.connected){state.view='settings';state.settingTab='Calendar';render();return;}toast('Finding free space in your calendar…');const out=await api('calendar/sync',{});state.calendar=out;render();toast(`Calendar updated: ${out.state?.plan?.scheduled?.length||0} task blocks planned.`);}
function autoSchedule(){clearTimeout(scheduleTimeout);if(!state.demo&&state.settings.autoSchedule&&state.calendar?.connected)scheduleTimeout=setTimeout(()=>syncCalendar().catch(e=>toast(e.message)),3000);}
document.addEventListener('click',async event=>{const target=event.target.closest('[data-action]');if(!target)return;const a=target.dataset.action,id=target.dataset.id;try{if(a==='docs'||a.startsWith('doc-')){await docAction(a,target);return;}switch(a){case 'entry-login':state.entryInteracted=true;authModal();break;case 'entry-signup':state.entryInteracted=true;authModal('signup');break;case 'entry-demo':enterDemo();break;case 'nav':state.view=target.dataset.view;state.filter='';render();break;case 'show-projects':state.view='projects';render();break;case 'menu':$('.sidebar').classList.toggle('open');break;case 'open-project':state.projectId=id;state.view='board';state.filter='';state.epicFilter='';render();break;case 'new-project':projectModal();break;case 'edit-project':projectModal(true);break;case 'new-task':await taskModal(null,false,target.dataset.status||'Ready');break;case 'new-routine':await taskModal(null,true);break;case 'task-detail':await taskModal(id);break;case 'contexts':contextModal();break;case 'close-modal':closeModal();break;case 'account':state.user?(state.view='settings',state.settingTab='Profile',render()):authModal();break;case 'account-action':state.user?await logout():authModal();break;case 'auth-mode':{const email=$('#auth-form [name="email"]')?.value||'';authModal(target.dataset.mode);$('#auth-form [name="email"]').value=email;break;}case 'logout':await logout();break;case 'skip':state.skip.push(id);render();break;case 'reset-skip':state.skip=[];render();break;case 'complete':{const {p,t}=findTask(id);if(!t)break;await mutate(p,d=>{d.tasks=d.tasks.map(k=>k.id===id?completeTask(k,dateToday()):k)});if(state.focus?.taskId===id){state.focus=null;localStorage.removeItem('orbit-focus');}closeModal();toast(t.repeat&&t.repeat!=='Never'?'Done. Your next repetition is ready for its next date.':'One less thing to carry. Task complete.');break;}case 'start-task':focusModal(id);break;case 'pause-focus':{const f=state.focus;if(!f)break;if(f.paused){f.end=Date.now()+f.remaining;f.paused=false;}else{f.remaining=Math.max(0,f.end-Date.now());f.paused=true;}if(!state.demo)localStorage.setItem('orbit-focus',JSON.stringify(f));break;}case 'settings-tab':state.settingTab=target.dataset.tab;render();break;case 'calendar-settings':state.view='settings';state.settingTab='Calendar';render();break;case 'galaxy-project':state.galaxyProject=id;render();break;case 'galaxy-back':state.galaxyProject=null;state.hideDone=false;render();break;case 'galaxy-done':state.hideDone=!state.hideDone;render();break;case 'new-epic':modal('Connect a few stars.',`<form id="epic-form">${field('Epic name','name','','text','required maxlength="80" placeholder="A goal these tasks share"')}<div class="modal-footer"><button type="submit" class="primary">Add epic</button></div></form>`);break;case 'members':await membersModal(id||state.projectId);break;case 'create-invite':{target.disabled=true;const out=await api('invite',{projectId:id});const link=location.origin+'/?invite='+out.token;$('#invite-result').innerHTML=`<div class="invite-link">${esc(link)}</div>${button('Copy invitation','copy-invite','small',`data-link="${esc(link)}"`)}`;target.disabled=false;break;}case 'copy-invite':await navigator.clipboard.writeText(target.dataset.link);toast('Invitation link copied.');break;case 'remove-member':await api('members/remove',{projectId:id,userId:target.dataset.user});await membersModal(id);break;case 'delete-task':{const {p,t}=findTask(id);modal('Delete this task?',`<p class="muted">“${esc(t.title)}” will be removed. Tasks depending on it will stay blocked until you edit their dependencies.</p><div class="modal-footer">${button('Keep task','close-modal')}${button('Delete task','confirm-delete-task','danger',`data-id="${id}"`)}</div>`);break;}case 'confirm-delete-task':{const {p}=findTask(id);await mutate(p,d=>{d.tasks=d.tasks.filter(t=>t.id!==id)});closeModal();toast('Task deleted.');break;}case 'delete-project':modal('Delete this project?',`<p class="muted">This removes the project, all its tasks, and member access. Export your workspace first if you want to keep a copy.</p><div class="modal-footer">${button('Keep project','close-modal')}${button('Delete project','confirm-delete-project','danger',`data-id="${id}"`)}</div>`);break;case 'confirm-delete-project':if(!state.demo)await api('project/delete',{id});state.projects=state.projects.filter(p=>p.id!==id);state.view='projects';persist();closeModal();render();autoSchedule();break;case 'sync-calendar':await syncCalendar();break;case 'connect-google':if(state.demo){authModal();toast('Sign in before connecting your calendar.');}else if(!state.config.googleConfigured)toast('Google OAuth credentials must be added to this app’s Vercel settings first.');else location.assign('/api/google/connect');break;case 'disconnect-calendar':await api('calendar/disconnect',{});state.calendar=null;render();toast('Google disconnected. Existing calendar events were kept.');break;case 'export':{const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),projects:state.projects,settings:state.settings},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='orbit-workspace-'+dateToday()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}case 'join-invite':{if(!state.user){authModal();break;}const token=sessionStorage.getItem('orbit-invite');await api('invite/join',{token});sessionStorage.removeItem('orbit-invite');closeModal();await loadCloud();state.view='projects';render();toast('You joined the project.');break;}}}catch(e){toast(e.message);target.disabled=false;}});
document.addEventListener('keydown',e=>{const t=e.target.closest('[role="button"][data-action]');if(t&&(e.key==='Enter'||e.key===' ')){e.preventDefault();t.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
document.addEventListener('change',async e=>{const el=e.target;try{if(el.dataset.pref){state.settings[el.dataset.pref]=el.dataset.pref==='minutes'?Number(el.value):el.value;state.skip=[];persist();render();if(!state.demo)await api('preferences',{data:state.settings});}if(el.id==='epic-filter'){state.epicFilter=el.value;render();}if(el.id==='task-project-select'){const p=project(el.value);$('#task-epic-select').innerHTML='<option value="">Independent task</option>'+p.data.epics.map(k=>`<option value="${k.id}">${esc(k.name)}</option>`).join('');const deps=$('select[name="dependencies"]');deps.innerHTML=p.data.tasks.map(k=>`<option value="${k.id}">${esc(k.title)}</option>`).join('');const assigned=$('select[name="assignee"]');assigned.innerHTML='<option value="">Unassigned</option>'+(state.user?`<option value="${state.user.id}">Me</option>`:'');}}catch(e){toast(e.message);}});
